import { prisma } from "@/db";
import {
  groupAssetsByBeat,
  videoScriptStatusSchema,
  type VideoScriptPayload,
  type VideoScriptStatus,
} from "@/services/videoScript/videoScriptTypes";
import { z } from "zod";

const newsStoryIdSchema = z.uuid("newsStoryId must be a uuid");
const scriptIdSchema = z.string().min(1, "scriptId is required");
const userIdSchema = z.string().min(1, "userId is required");

const createVideoScriptSchema = z.object({
  newsId: newsStoryIdSchema,
  userId: userIdSchema,
  language: z.string().min(1),
  minSec: z.number().int(),
  maxSec: z.number().int(),
  pace: z.string().min(1),
  aspectRatio: z.string().min(1),
});

export async function createVideoScript(
  input: z.input<typeof createVideoScriptSchema>,
) {
  const data = createVideoScriptSchema.parse(input);
  return prisma.videoScript.create({ data: { ...data, status: "queued" } });
}

export async function findLatestVideoScriptForUser(
  newsId: string,
  userId: string,
) {
  return prisma.videoScript.findFirst({
    where: {
      newsId: newsStoryIdSchema.parse(newsId),
      userId: userIdSchema.parse(userId),
    },
    orderBy: { createdAt: "desc" },
    include: { assets: { orderBy: [{ beatIndex: "asc" }, { rank: "asc" }] } },
  });
}

export async function getVideoScriptById(scriptId: string) {
  return prisma.videoScript.findUnique({
    where: { id: scriptIdSchema.parse(scriptId) },
  });
}

export async function setVideoScriptStatus(
  scriptId: string,
  status: VideoScriptStatus,
) {
  return prisma.videoScript.update({
    where: { id: scriptIdSchema.parse(scriptId) },
    data: { status: videoScriptStatusSchema.parse(status), error: null },
  });
}

export async function markVideoScriptFailed(scriptId: string, error: string) {
  return prisma.videoScript.update({
    where: { id: scriptIdSchema.parse(scriptId) },
    data: { status: "failed", error: error.slice(0, 4000) },
  });
}

type VideoScriptWithAssets = NonNullable<
  Awaited<ReturnType<typeof findLatestVideoScriptForUser>>
>;

export function serializeVideoScript(
  row: VideoScriptWithAssets,
): VideoScriptPayload {
  const { assets, createdAt, updatedAt, userId: _userId, ...rest } = row;
  const parsedStatus = videoScriptStatusSchema.safeParse(rest.status);
  return {
    ...rest,
    status: parsedStatus.success ? parsedStatus.data : "failed",
    createdAt: createdAt.toISOString(),
    updatedAt: updatedAt.toISOString(),
    assetsByBeat: groupAssetsByBeat(
      assets.map(({ scriptId: _scriptId, ...asset }) => asset),
    ),
  };
}

/**
 * Video script pipeline (Inngest)
 *
 * Event: `video/script.requested`
 * Trigger: `POST /api/news/stories/[storyId]/script` after creating a queued `VideoScript`.
 *
 * Stages (each sets `VideoScript.status`):
 * researching → scripting → fact_checking → directing → finding_images →
 * prompting → packaging → building → done
 *
 * Phase 1: stages are stubs that only advance the status (with a short pause so
 * the stepper is visible). Agents land in later phases.
 *
 * onFailure marks the row `failed` with the error message.
 */

import { createPipelineLogger } from "@/clients/pipelineLogger";
import { inngest } from "@/clients/inngestClient";
import {
  getVideoScriptById,
  markVideoScriptFailed,
  setVideoScriptStatus,
} from "@/repositories/videoScript";
import {
  VIDEO_SCRIPT_STAGES,
} from "@/services/videoScript/videoScriptTypes";
import { z } from "zod";

export const VIDEO_SCRIPT_REQUESTED_EVENT = "video/script.requested" as const;

export const videoScriptRequestedEventDataSchema = z.object({
  scriptId: z.string().min(1),
});

export type VideoScriptRequestedEventData = z.infer<
  typeof videoScriptRequestedEventDataSchema
>;

const pipelineLog = createPipelineLogger("[video-script-pipeline]");

/** Phase 1 only: lets the stepper show each stage before agents exist. */
const STUB_STAGE_PAUSE = "1.5s";

export function enqueueVideoScriptPipeline(data: VideoScriptRequestedEventData) {
  return inngest.send({
    name: VIDEO_SCRIPT_REQUESTED_EVENT,
    data: videoScriptRequestedEventDataSchema.parse(data),
  });
}

export const generateVideoScriptFunction = inngest.createFunction(
  {
    id: "generate-video-script",
    name: "Generate video script",
    triggers: [{ event: VIDEO_SCRIPT_REQUESTED_EVENT }],
    idempotency: "event.data.scriptId",
    timeouts: { finish: "30m" },
    onFailure: async ({ event, error, step }) => {
      const parsed = videoScriptRequestedEventDataSchema.safeParse(event.data);
      if (!parsed.success) {
        pipelineLog("onFailure", "invalid event data");
        return;
      }
      const message = error instanceof Error ? error.message : String(error);
      await step.run("mark-video-script-failed", async () => {
        await markVideoScriptFailed(parsed.data.scriptId, message);
      });
    },
  },
  async ({ event, step }) => {
    const { scriptId } = videoScriptRequestedEventDataSchema.parse(event.data);

    const loaded = await step.run("load-video-script", async () => {
      const row = await getVideoScriptById(scriptId);
      if (!row) {
        throw new Error("Video script not found");
      }
      return { status: row.status };
    });
    if (loaded.status === "done") {
      pipelineLog("load-video-script", "already done", { scriptId });
      return { scriptId, status: "done" };
    }

    for (const stage of VIDEO_SCRIPT_STAGES) {
      await step.run(`stage-${stage.status}`, async () => {
        pipelineLog(`stage-${stage.status}`, "start", { scriptId });
        await setVideoScriptStatus(scriptId, stage.status);
        return { status: stage.status };
      });
      await step.sleep(`stub-pause-${stage.status}`, STUB_STAGE_PAUSE);
    }

    await step.run("mark-video-script-done", async () => {
      await setVideoScriptStatus(scriptId, "done");
    });

    return { scriptId, status: "done" };
  },
);

import { enqueueVideoScriptPipeline } from "@/inngest/generateVideoScript";
import { getNewsStoryWithSourcesForPage } from "@/repositories/newsStory";
import {
  createVideoScript,
  findLatestVideoScriptForUser,
  markVideoScriptFailed,
  serializeVideoScript,
} from "@/repositories/videoScript";
import {
  resolveMinSec,
  shouldReuseVideoScript,
  type CreateVideoScriptBody,
  type VideoScriptPayload,
} from "@/services/videoScript/videoScriptTypes";
import { z } from "zod";

/** Same visibility as the story page; `null` when missing or not viewable. */
async function canAccessStory(storyId: string, userId: string) {
  if (!z.uuid().safeParse(storyId).success) {
    return false;
  }
  const bundle = await getNewsStoryWithSourcesForPage(storyId, userId);
  return bundle != null;
}

export async function getLatestVideoScript(input: {
  storyId: string;
  userId: string;
}): Promise<{ videoScript: VideoScriptPayload | null } | null> {
  if (!(await canAccessStory(input.storyId, input.userId))) {
    return null;
  }
  const row = await findLatestVideoScriptForUser(input.storyId, input.userId);
  return { videoScript: row ? serializeVideoScript(row) : null };
}

/**
 * Reuses the latest script for this user + story unless `regenerate` is set or
 * it failed; otherwise creates a queued row and enqueues the pipeline.
 */
export async function startVideoScript(input: {
  storyId: string;
  userId: string;
  body: CreateVideoScriptBody;
}): Promise<{ scriptId: string; reused: boolean } | null> {
  if (!(await canAccessStory(input.storyId, input.userId))) {
    return null;
  }

  const latest = await findLatestVideoScriptForUser(
    input.storyId,
    input.userId,
  );
  if (latest && shouldReuseVideoScript(latest, input.body.regenerate)) {
    return { scriptId: latest.id, reused: true };
  }

  const created = await createVideoScript({
    newsId: input.storyId,
    userId: input.userId,
    language: input.body.language,
    minSec: resolveMinSec(input.body.maxSec),
    maxSec: input.body.maxSec,
    pace: input.body.pace,
    aspectRatio: input.body.aspectRatio,
  });

  try {
    await enqueueVideoScriptPipeline({ scriptId: created.id });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to start pipeline";
    await markVideoScriptFailed(created.id, message);
    throw error;
  }

  return { scriptId: created.id, reused: false };
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { requireAuthenticatedUser } from "@/lib/auth";
import {
  getLatestVideoScript,
  startVideoScript,
} from "@/services/videoScript/videoScriptService";
import { createVideoScriptBodySchema } from "@/services/videoScript/videoScriptTypes";

type RouteContext = {
  params: Promise<{ storyId: string }>;
};

/** Latest video script for the signed-in user + story, assets grouped by beat. */
export async function GET(_request: Request, context: RouteContext) {
  const user = await requireAuthenticatedUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { storyId } = await context.params;
  try {
    const result = await getLatestVideoScript({ storyId, userId: user.id });
    if (!result) {
      return NextResponse.json({ error: "Not found" }, { status: 404 });
    }
    return NextResponse.json(result);
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to load video script";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

/** Create (or reuse, unless `regenerate`) a video script and start the pipeline. */
export async function POST(request: Request, context: RouteContext) {
  const user = await requireAuthenticatedUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const parsed = createVideoScriptBodySchema.safeParse(body ?? {});
  if (!parsed.success) {
    return NextResponse.json(
      {
        error: parsed.error.issues[0]?.message ?? "Validation failed",
        details: z.treeifyError(parsed.error),
      },
      { status: 400 },
    );
  }

  const { storyId } = await context.params;
  try {
    const result = await startVideoScript({
      storyId,
      userId: user.id,
      body: parsed.data,
    });
    if (!result) {
      return NextResponse.json({ error: "Not found" }, { status: 404 });
    }
    return NextResponse.json(result, { status: result.reused ? 200 : 201 });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to start video script";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

